// Rocq: Pascal.pascal_implem.sd_loop (local: sd_loop)
// Variant: uncurried, lifted
pub fn sd_loop(n: u64, p: u64, _H: ()) -> u64 {
  let tmp = andb(ltb(p, n), leb(mul(p, p), n));
  match bdec(tmp) {
    sumbool::left => {
      let tmp_1 = mod_(n, p);
      if eqb(tmp_1, 0u64) {
        p
      } else {
        sd_loop(n, add(p, 1u64), ())
      }
    },
    sumbool::right => {
      n
    },
  }
}

// Rocq: Pascal.pascal_implem.pascal_impl
